cypress_script:
describe('Tool Shop Product Catalogue', () => {
  it('should search for a product and display results', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('#search-query').type('Hammer');
    cy.get('[data-test="search-submit"]').click();
    cy.url().should('include', 'search');
  });

  it('should not change the URL when searching with an empty query', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('[data-test="search-submit"]').click();
    cy.url().should('eq', 'https://practicesoftwaretesting.com/');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Tool Shop Product Catalogue', () => {
  test('should search for a product and display results', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.fill('#search-query', 'Hammer');
    await page.click('[data-test="search-submit"]');
    await expect(page).toHaveURL(/search/);
  });

  test('should not change the URL when searching with an empty query', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.click('[data-test="search-submit"]');
    await expect(page).toHaveURL('https://practicesoftwaretesting.com/');
  });
});
